// ═══ RULE 1: Return empty collection, NOT Optional<Collection> ═══

// ❌ BAD:
Optional<List<Trade>> findTrades(String accountId) {
    List<Trade> trades = tradeRepo.findByAccountId(accountId);
    return trades.isEmpty() ? Optional.empty() : Optional.of(trades);
}
// Caller: findTrades("X").orElse(Collections.emptyList()).forEach(...)
// Double wrapping! Empty list already means "no trades."

// ✅ GOOD:
List<Trade> findTrades(String accountId) {
    return tradeRepo.findByAccountId(accountId);  // returns empty list if none
}
// Caller: findTrades("X").forEach(...)  // empty list = no iterations, no NPE

// Same applies to: Set, Map, Stream, array
// Never: Optional<Set<T>>, Optional<Map<K,V>>, Optional<Stream<T>>
// Always: return empty Set/Map/Stream/array
