// ═══ RULE 2: Use primitive OptionalInt/Long/Double ═══

// ❌ BAD: Optional<Integer> boxes int → Integer (heap allocation!)
Optional<Integer> maxScore = trades.stream()
    .map(Trade::getRiskScore)       // Stream<Integer> — BOXING!
    .max(Integer::compareTo);        // Optional<Integer> — BOXING!

// ✅ GOOD: OptionalInt — pure primitives, zero boxing
OptionalInt maxScore = trades.stream()
    .mapToInt(Trade::getRiskScore)   // IntStream — primitives!
    .max();                           // OptionalInt — no boxing!

maxScore.ifPresent(score -> log.info("Max risk: {}", score));
maxScore.orElse(0);                  // default
maxScore.orElseThrow();              // fail fast

// OptionalLong, OptionalDouble — same pattern
OptionalLong totalAmount = trades.stream().mapToLong(Trade::getAmountCents).sum(); // wait, sum returns long
OptionalDouble avgPrice = trades.stream().mapToDouble(Trade::getPrice).average();  // OptionalDouble
