// ❌ BAD: 10 million Optional objects created and immediately garbage collected
for (int i = 0; i < 10_000_000; i++) {
    Optional<Trade> opt = Optional.ofNullable(cache.get(i));  // heap allocation!
    Trade trade = opt.orElse(defaultTrade);
}
// 10M Optional objects → GC pressure → pauses

// ✅ GOOD: plain null check in hot path
