// ─── File: src/main/java/com/bank/scoring/service/ScoringService.java ───
package com.bank.scoring.service;

import com.bank.scoring.dto.ScoringReport;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.util.*;
import java.util.stream.IntStream;

@Service
@Slf4j
public class ScoringService {

    record RiskFactor(String name, int score) {}

    // ═══ RULE 1: Return empty collection, NOT Optional<Collection> ═══

    // ❌ BAD:
    public Optional<List<RiskFactor>> findRiskFactorsBad(String accountId) {
        List<RiskFactor> factors = getRiskFactors(accountId);
        return factors.isEmpty() ? Optional.empty() : Optional.of(factors);
    }

    // ✅ GOOD:
    public List<RiskFactor> findRiskFactorsGood(String accountId) {
        return getRiskFactors(accountId);  // empty list if none — no Optional needed!
    }

    private List<RiskFactor> getRiskFactors(String accountId) {
        if ("SAV2001".equals(accountId)) {
            return List.of(new RiskFactor("LARGE_TRANSACTION", 8),
                new RiskFactor("INTERNATIONAL_WIRE", 9),
                new RiskFactor("NEW_ACCOUNT", 5));
        }
        return List.of();  // empty list — NOT null, NOT Optional
    }

    public ScoringReport demonstrateCollectionRule() {
        List<String> explanations = new ArrayList<>();

        // BAD: caller must unwrap Optional AND iterate
        Optional<List<RiskFactor>> badResult = findRiskFactorsBad("UNKNOWN");
        int badCount = badResult.map(List::size).orElse(0);
        explanations.add("❌ Optional<List>: " + badCount + " factors — double unwrap needed");

        // GOOD: caller just iterates (empty list = no iterations)
        List<RiskFactor> goodResult = findRiskFactorsGood("UNKNOWN");
        int goodCount = goodResult.size();
        explanations.add("✅ List (empty): " + goodCount + " factors — just iterate, zero unwrap");

        // With data:
        List<RiskFactor> factors = findRiskFactorsGood("SAV2001");
        explanations.add("✅ List (data): " + factors.size() + " factors");

        return new ScoringReport("COLLECTION_RULE", factors.size(), 0, 0, 0, explanations);
    }

    // ═══ RULE 2: Use OptionalInt instead of Optional<Integer> ═══

    public ScoringReport demonstratePrimitiveRule() {
        List<RiskFactor> factors = findRiskFactorsGood("SAV2001");
        List<String> explanations = new ArrayList<>();

        // ❌ BAD: Optional<Integer> — boxing!
        Optional<Integer> maxBoxed = factors.stream()
            .map(RiskFactor::score)              // Stream<Integer> — BOXING!
            .max(Integer::compareTo);             // Optional<Integer>
        explanations.add("❌ Optional<Integer>: max=" + maxBoxed.orElse(0) + " (boxed)");

        // ✅ GOOD: OptionalInt — no boxing!
        OptionalInt maxPrimitive = factors.stream()
            .mapToInt(RiskFactor::score)          // IntStream — primitives!
            .max();                                // OptionalInt
        explanations.add("✅ OptionalInt: max=" + maxPrimitive.orElse(0) + " (primitive)");

        // OptionalDouble for average
        OptionalDouble avg = factors.stream()
            .mapToInt(RiskFactor::score)
            .average();
        explanations.add("✅ OptionalDouble: avg=" +
            avg.orElse(0.0) + " (primitive double)");

        return new ScoringReport("PRIMITIVE_RULE", factors.size(),
            maxPrimitive.orElse(0), avg.orElse(0.0), 0, explanations);
    }

    // ═══ RULE 3: Avoid Optional in hot path ═══

    public ScoringReport demonstrateHotPathRule() {
        int iterations = 1_000_000;
        int[] scores = IntStream.range(0, iterations).map(i -> i % 10).toArray();
        List<String> explanations = new ArrayList<>();

        // ❌ BAD: Optional in hot loop
        long start1 = System.nanoTime();
        int sum1 = 0;
        for (int score : scores) {
            sum1 += Optional.of(score).orElse(0);  // creates 1M Optional objects!
        }
        long dur1 = System.nanoTime() - start1;
        explanations.add("❌ Optional in loop: sum=" + sum1 + " in " + dur1/1000 + "μs");

        // ✅ GOOD: plain value in hot loop
        long start2 = System.nanoTime();
        int sum2 = 0;
        for (int score : scores) {
            sum2 += score;  // zero allocation
        }
        long dur2 = System.nanoTime() - start2;
        explanations.add("✅ Plain value: sum=" + sum2 + " in " + dur2/1000 + "μs");

        explanations.add("Speedup: " + (dur1 / Math.max(dur2, 1)) + "x faster without Optional");

        return new ScoringReport("HOT_PATH_RULE", iterations, 0, 0, dur2, explanations);
    }
}
