package com.bank.scoring.service;

import org.junit.jupiter.api.Test;
import java.util.*;
import java.util.stream.IntStream;
import static org.assertj.core.api.Assertions.*;

class OptionalPitfallsTest {

    @Test
    void returnEmptyCollectionNotOptionalCollection() {
        // ❌ Optional<List<String>>:
        Optional<List<String>> bad = Optional.of(List.of());  // empty list wrapped in Optional — WHY?

        // ✅ Just List<String>:
        List<String> good = List.of();  // empty list IS the answer

        assertThat(bad.get()).isEmpty();
        assertThat(good).isEmpty();
        // Both represent "no results" — Optional adds nothing, just complexity
    }

    @Test
    void useOptionalIntNotOptionalInteger() {
        // ❌ Optional<Integer> — boxing:
        Optional<Integer> boxed = IntStream.of(1, 2, 3).boxed().max(Integer::compareTo);

        // ✅ OptionalInt — no boxing:
        OptionalInt primitive = IntStream.of(1, 2, 3).max();

        assertThat(boxed).contains(3);
        assertThat(primitive.orElse(0)).isEqualTo(3);
    }

    @Test
    void optionalIntApi() {
        OptionalInt present = OptionalInt.of(780);
        OptionalInt absent = OptionalInt.empty();

        assertThat(present.isPresent()).isTrue();
        assertThat(present.orElse(0)).isEqualTo(780);
        assertThat(absent.orElse(0)).isEqualTo(0);
        present.ifPresent(score -> assertThat(score).isEqualTo(780));
    }

    @Test
    void emptyCollectionIsAlreadyAbsence() {
        List<String> trades = List.of();  // empty = "no trades"

        // No null check needed:
        trades.forEach(t -> { /* never executes — zero iterations */ });
        assertThat(trades.stream().count()).isZero();
        assertThat(trades.isEmpty()).isTrue();

        // Optional<List> adds NOTHING to this — the list handles absence itself
    }
}
